-- Jalankan setelah supabase/blog-posts.sql di SQL Editor Supabase.
-- Artikel diterbitkan sekali; ON CONFLICT menjaga artikel yang sudah ada tetap utuh.
begin;
insert into public.blog_posts (
  slug, title, excerpt, content, category, author, author_url, cover_image_url,
  published, published_at, updated_at
)
select
  seed.slug, seed.title, seed.excerpt, seed.content, seed.category, seed.author,
  seed.author_url, seed.cover_image_url, seed.published, now(), now()
from jsonb_to_recordset(
$blog_seed$
[
  {
    "slug": "panduan-memilih-software-office-untuk-kuliah-dan-kerja",
    "title": "Panduan Memilih Software Office untuk Kuliah dan Kerja",
    "excerpt": "Pilih aplikasi dokumen, spreadsheet, dan presentasi berdasarkan tugas, format berkas, perangkat, serta cara kolaborasi yang benar-benar kamu perlukan.",
    "content": "Memilih aplikasi Office akan lebih mudah kalau dimulai dari pekerjaan yang harus selesai. Mahasiswa mungkin paling sering menyusun makalah, mengolah tabel penelitian, dan membuat presentasi. Tim kerja bisa lebih sering bertukar dokumen, membuat laporan, atau mengedit berkas bersama. Daftar kebutuhan itu membantu kamu memilih versi aplikasi dan perangkat yang sesuai.\n\n## Petakan tiga jenis pekerjaan\n\nUntuk dokumen, pastikan aplikasi yang dipilih dapat membuka dan menyimpan format yang dipakai kampus atau kantor, misalnya DOCX dan PDF. Untuk spreadsheet, cek apakah rumus, grafik, dan format berkas tetap terbaca ketika dikirim ke orang lain. Excel mendukung beberapa format, tetapi Microsoft mengingatkan bahwa saat berkas disimpan ke format lain, sebagian format atau fitur bisa berubah. Simpan salinan asli sebelum mengonversi.\n\nUntuk presentasi, tanyakan format apa yang diminta dosen atau klien. Coba buka berkas di perangkat yang akan dipakai saat presentasi. Font, video, animasi, dan rasio layar dapat membuat tampilan berbeda antar perangkat.\n\n## Cek cara menyimpan dan berkolaborasi\n\nJika kamu mengedit berkas di beberapa perangkat, periksa dukungan akun, penyimpanan cloud, dan kebutuhan internet pada versi yang dipilih. Microsoft menjelaskan bahwa menyimpan dokumen ke OneDrive atau SharePoint dapat menyediakan AutoSave dan Version History untuk skenario yang didukung. Fitur tersebut tetap bergantung pada akun, lokasi simpan, dan edisi aplikasi.\n\nApa pun aplikasinya, biasakan memberi nama berkas yang jelas, menyimpan versi final di folder khusus, dan membuat cadangan sebelum perubahan besar. Untuk tugas kelompok, tentukan satu berkas utama agar tidak ada beberapa versi final yang saling tertukar.\n\n## Cocokkan versi dengan perangkat\n\nSebelum memasang aplikasi, catat sistem operasi dan versinya, kapasitas penyimpanan kosong, serta apakah perangkat pribadi atau milik kampus. Pastikan versi Office yang dipilih dapat berjalan pada perangkat tersebut dan mendukung format yang dipakai rekan kerja. Ketersediaan fitur juga dapat berbeda antara aplikasi desktop, web, dan paket tertentu.\n\nJika kamu mempertimbangkan [produk Office di katalog Aplikasi.id](/produk/app-office), baca keterangan produk dan tanyakan secara tertulis versi, perangkat yang didukung, jenis lisensi, cara aktivasi, masa berlaku, dan kebijakan pembaruan. Jangan menganggap label Office saja menjelaskan semua hal itu.\n\n## Daftar cek sebelum mulai\n\n- Format dokumen, spreadsheet, dan presentasi yang harus dikirim.\n- Sistem operasi serta versi aplikasi yang kompatibel.\n- Apakah pekerjaan memerlukan akun dan koneksi internet.\n- Lokasi simpan, pencadangan, dan cara berbagi berkas.\n- Ketentuan lisensi dan dukungan yang kamu terima.\n\nMenjawab lima hal ini lebih berguna daripada memilih aplikasi hanya dari banyaknya fitur. Setelah aplikasi dipasang, uji dengan salinan berkas tugas terlebih dahulu dan pastikan hasil ekspornya bisa dibuka di perangkat tujuan.\n\n## Rujukan resmi\n\n- [Microsoft: menyimpan berkas Office](https://support.microsoft.com/en-us/office/collab-files/save-your-files)\n- [Microsoft: format berkas yang didukung Excel](https://support.microsoft.com/en-us/excel/file-formats-that-are-supported-in-excel)",
    "category": "Office & Produktivitas",
    "author": "Aplikasi.id",
    "author_url": null,
    "cover_image_url": null,
    "published": true
  },
  {
    "slug": "cara-menyiapkan-data-kuesioner-untuk-analisis-spss",
    "title": "Cara Menyiapkan Data Kuesioner sebelum Dianalisis di SPSS",
    "excerpt": "Rapikan struktur data, kode jawaban, label variabel, dan nilai kosong sebelum menjalankan analisis agar hasil penelitian lebih mudah diperiksa.",
    "content": "Kesalahan analisis sering dimulai jauh sebelum tombol Analyze ditekan: nama kolom tidak konsisten, kode jawaban berubah-ubah, atau nilai kosong dianggap sebagai angka. Menyiapkan data lebih awal membuat hasil lebih mudah ditelusuri dan dibahas bersama dosen pembimbing.\n\n## Buat satu baris untuk satu responden\n\nSusun tabel dengan satu baris untuk setiap responden dan satu kolom untuk setiap variabel. Tambahkan ID anonim yang tidak memuat nama, nomor telepon, atau informasi pribadi. Simpan pertanyaan dan aturan pengkodean dalam buku kode terpisah. Contohnya, variabel jenis_kelamin dapat memiliki kode angka dengan label yang kamu definisikan secara konsisten. Jangan mengubah arti kode yang sama di tengah pengolahan.\n\n## Bedakan jawaban kosong dari nilai nol\n\nNilai 0 dapat menjadi jawaban yang sah, misalnya jumlah kejadian dalam periode tertentu. Jika responden tidak menjawab, jangan otomatis mengisinya dengan 0. Tentukan cara menandai jawaban kosong dan dokumentasikan alasannya. IBM menjelaskan bahwa nilai hilang dapat berupa system-missing atau user-missing; definisi tersebut memengaruhi kasus yang masuk ke perhitungan statistik.\n\nPada data skala, catat satuan dan rentangnya. Untuk jawaban kategori, gunakan kode yang tetap dan tambahkan label nilai. Periksa juga apakah ada nilai di luar rentang kuesioner, seperti skor 6 pada skala 1–5.\n\n## Impor dan periksa sebelum menguji hipotesis\n\nSimpan salinan data mentah tanpa perubahan. Impor salinan kerja ke [SPSS yang tersedia di katalog](/produk/app-spssmac) dan periksa nama variabel, tipe data, label, serta beberapa baris pertama. Gunakan tabel frekuensi atau statistik deskriptif untuk menemukan nilai tak masuk akal dan jumlah respons kosong. Pastikan setiap kolom sudah mewakili konsep yang tepat.\n\nJangan menghapus atau mengganti nilai hilang tanpa alasan metodologis. Penanganannya bergantung pada desain penelitian dan asumsi analisis. IBM mencatat bahwa cara menangani missing values dapat mengubah kasus yang digunakan untuk statistik; diskusikan pilihan tersebut dengan pembimbing dan tuliskan keputusanmu di metode penelitian.\n\n## Simpan keputusan analisis\n\nCatat sumber data, tanggal pembersihan, perubahan yang dilakukan, variabel yang dikeluarkan, dan alasan setiap keputusan. Simpan file kerja terpisah dari data mentah dan ekspor tabel hasil dengan nama yang menjelaskan analisisnya. Dengan begitu, orang lain bisa mengikuti alur dari data menuju kesimpulan.\n\nSPSS membantu menghitung dan menyusun output, tetapi tidak menentukan apakah desain penelitian tepat atau apakah hubungan yang ditemukan bersifat sebab-akibat. Interpretasi harus merujuk pada pertanyaan riset, metode, ukuran sampel, batasan data, dan literatur yang relevan.\n\n## Rujukan resmi\n\n- [IBM: struktur dan kamus data berkas SPSS](https://www.ibm.com/docs/en/spss-statistics/31.0.0?topic=files-spss-statistics-data)\n- [IBM: jenis nilai hilang](https://www.ibm.com/docs/en/spss-statistics/30.0.0?topic=tables-missing-values)\n- [IBM: cara DESCRIPTIVES menangani nilai hilang](https://www.ibm.com/docs/en/spss-statistics/31.0.0?topic=descriptives-missing-subcommand-command)",
    "category": "Riset & Statistik",
    "author": "Aplikasi.id",
    "author_url": null,
    "cover_image_url": null,
    "published": true
  },
  {
    "slug": "photoshop-atau-lightroom-memilih-alur-edit-foto",
    "title": "Photoshop atau Lightroom? Pilih Alur Edit Foto yang Tepat",
    "excerpt": "Kenali kapan alur katalog dan penyuntingan banyak foto lebih praktis, dan kapan kamu membutuhkan penyuntingan lokal yang lebih terperinci.",
    "content": "Photoshop dan Lightroom sama-sama dipakai dalam pekerjaan fotografi, tetapi cara kerjanya tidak harus saling menggantikan. Pilih berdasarkan jumlah foto, jenis perubahan, dan bagaimana kamu ingin menyimpan hasil edit.\n\n## Saat kamu mengolah satu kumpulan foto\n\nUntuk sesi pemotretan, foto produk, atau dokumentasi acara, pekerjaan pertama biasanya memilah foto, memberi penilaian, mengatur warna dasar, lalu mengekspor banyak gambar dengan ukuran yang konsisten. Alur katalog membantu menjaga foto tetap terorganisasi. Buat folder proyek, gunakan nama yang mudah dicari, dan tentukan ukuran ekspor sesuai tujuan: layar, unggahan web, atau kebutuhan cetak.\n\nJangan menghapus file kamera sebelum hasil akhir dan cadangannya diperiksa. Simpan satu salinan sumber di lokasi terpisah dari folder hasil agar kamu dapat kembali ke foto awal.\n\n## Saat perubahan perlu dilakukan pada bagian tertentu\n\nPhotoshop lebih sesuai ketika satu gambar perlu komposisi beberapa elemen, retouch lokal, teks, atau pengaturan objek yang lebih rinci. Layer mask dapat menyembunyikan atau menampilkan bagian layer tanpa langsung menghapus isi layer tersebut. Prinsip ini membantu kamu mencoba perubahan sambil menjaga bagian sumber tetap tersedia.\n\nAdobe juga menyediakan alur untuk membuka foto dari Lightroom ke Photoshop, mengerjakan retouch atau komposisi, lalu menyimpan hasil agar muncul kembali di pustaka Lightroom. Periksa pengaturan dokumen dan jangan menimpa satu-satunya salinan asli.\n\n## Contoh alur kerja sederhana\n\n1. Salin foto ke folder proyek dan buat cadangan.\n2. Pilih foto yang layak diproses dan kelompokkan menurut kebutuhan.\n3. Kerjakan koreksi umum pada kumpulan foto.\n4. Buka beberapa foto terpilih di [Photoshop](/produk/app-photoshop) untuk retouch lokal atau komposisi.\n5. Periksa hasil pada ukuran tujuan dan ekspor salinan final.\n6. Buka hasil akhir di perangkat atau aplikasi yang akan memakainya.\n\nUntuk foto perjalanan dengan banyak gambar, katalog dan ekspor batch dapat menghemat langkah. Untuk poster promosi atau foto yang memerlukan penggabungan elemen, penyuntingan berbasis layer lebih relevan. [Lightroom Classic di katalog](/produk/app-lightroom) dan Photoshop dapat masuk dalam satu workflow, tetapi kebutuhanmu menentukan apakah perlu menggunakan keduanya.\n\n## Periksa sebelum membeli atau memasang\n\nPastikan versi aplikasi sesuai dengan sistem operasi dan perangkat. Cek juga kebutuhan penyimpanan karena file foto beresolusi tinggi dan salinan hasil edit dapat memakan ruang. Baca ketentuan lisensi, cara aktivasi, dukungan pembaruan, dan proses bantuan untuk versi yang ditawarkan.\n\n## Rujukan resmi\n\n- [Adobe: mengedit foto Lightroom di Photoshop](https://helpx.adobe.com/ca/lightroom/desktop/using/edit-in-lightroom-and-photoshop.html)\n- [Adobe: cara kerja layer mask di Photoshop](https://helpx.adobe.com/photoshop/using/editing-layer-masks.html)",
    "category": "Desain & Fotografi",
    "author": "Aplikasi.id",
    "author_url": null,
    "cover_image_url": null,
    "published": true
  },
  {
    "slug": "kapan-menggunakan-coreldraw-untuk-desain-vektor",
    "title": "Kapan Menggunakan CorelDRAW untuk Desain Vektor?",
    "excerpt": "Pahami perbedaan dasar gambar vektor dan raster, lalu siapkan file desain agar mudah diedit dan siap diperiksa sebelum dicetak.",
    "content": "Logo, ikon, ilustrasi, dan materi cetak sering perlu digunakan pada ukuran yang berbeda. Sebelum memilih aplikasi, tentukan jenis aset yang sedang dibuat dan bagaimana file itu akan diserahkan.\n\n## Vektor dan raster menyelesaikan kebutuhan berbeda\n\nGambar vektor dibentuk dari garis dan kurva, sehingga objek dapat diubah ukurannya tanpa tersusun dari kotak-kotak piksel seperti gambar raster. Karakter ini berguna untuk logo, simbol, ilustrasi garis, dan bentuk yang perlu dicetak pada beberapa ukuran. Foto biasanya berupa raster dan memerlukan pengolahan piksel.\n\nCorelDRAW menyediakan alat gambar vektor untuk membangun objek, mengubah kurva, memberi warna, dan mengatur teks. [CorelDRAW Academy](https://www.coreldraw.com/en/academy/tools/) memiliki latihan resmi tentang menggambar vektor, bentuk, dan teks. Cobalah latihan dasar lebih dulu sebelum membuat file untuk klien atau percetakan.\n\n## Alur membuat file yang mudah diperiksa\n\nMulai dari ukuran halaman dan tujuan akhir. Untuk logo, tanyakan versi warna dan latar yang dibutuhkan. Untuk desain cetak, minta spesifikasi dari percetakan mengenai ukuran, area potong, mode warna, dan format file. Persyaratan cetak dapat berbeda, jadi jangan menebak nilai bleed atau profil warna.\n\nPisahkan elemen penting ke layer atau kelompok yang jelas. Gunakan nama objek yang masuk akal, periksa teks pada ukuran sebenarnya, dan simpan file kerja yang tetap bisa diedit. Jika file harus dikirim dalam bentuk yang lebih umum, ekspor salinan sesuai spesifikasi penerima dan minta mereka memeriksa hasilnya.\n\n## Checklist sebelum menyerahkan desain\n\n- Pastikan ukuran halaman dan rasio sesuai permintaan.\n- Tinjau ejaan, jarak, kontras, dan elemen yang terpotong.\n- Periksa font yang digunakan dan sepakati cara penanganannya dengan penerima.\n- Simpan file sumber terpisah dari file ekspor.\n- Buka hasil ekspor untuk memastikan tampilannya tidak berubah.\n\n[CorelDRAW di katalog Aplikasi.id](/produk/app-coreldraw) dapat dipertimbangkan bila pekerjaanmu banyak memakai ilustrasi dan tata letak vektor. Untuk foto dan retouch piksel, aplikasi seperti [Photoshop](/produk/app-photoshop) memiliki alur kerja yang berbeda. Keduanya dapat melengkapi satu proyek, tetapi tidak setiap desain memerlukan dua aplikasi.\n\nSebelum memasang, cocokkan versi, sistem operasi, lisensi, dan dukungan yang tertulis pada penawaran. Simpan satu salinan master dan uji ekspor pada perangkat yang akan digunakan untuk produksi.\n\n## Rujukan resmi\n\n- [CorelDRAW Academy: menggambar vektor dan mempelajari alat](https://www.coreldraw.com/en/academy/tools/)\n- [CorelDRAW: panduan memulai seni vektor](https://www.coreldraw.com/en/learn/guide-to-vector-design/get-started-making-vector-art/)",
    "category": "Desain Grafis",
    "author": "Aplikasi.id",
    "author_url": null,
    "cover_image_url": null,
    "published": true
  },
  {
    "slug": "autocad-vs-sketchup-memilih-aplikasi-untuk-proyek",
    "title": "AutoCAD atau SketchUp? Mulai dari Keluaran Proyekmu",
    "excerpt": "Pilih aplikasi berdasarkan hasil yang harus diserahkan: gambar teknis, model ruang, presentasi konsep, atau kombinasi beberapa format.",
    "content": "AutoCAD dan SketchUp sama-sama muncul dalam pekerjaan desain ruang dan bangunan, tetapi pemilihan software sebaiknya mengikuti keluaran proyek. Jangan mulai dari daftar fitur yang panjang. Tanyakan dulu file apa yang diminta, siapa yang akan membukanya, dan seberapa rinci gambar perlu diperiksa.\n\n## Pilih berdasarkan tugas utama\n\nJika tugas berpusat pada gambar teknis berdimensi dan pertukaran berkas gambar, periksa apakah format dan versi AutoCAD yang dipakai tim cocok dengan standar proyek. Tanyakan layer, unit, skala, aturan penamaan, serta format ekspor yang diterima. Kesesuaian dengan workflow pihak lain sering lebih penting daripada mencoba semua toolbar.\n\nJika kamu perlu menyampaikan bentuk ruang atau volume dengan cepat kepada klien atau rekan, pemodelan 3D konseptual dapat membantu orang membayangkan hubungan antar ruang. SketchUp menyediakan panduan dan persyaratan sistem yang berbeda menurut versinya; [lihat dokumentasi resmi SketchUp](https://help.sketchup.com/en/sketchup/system-requirements) sebelum memasang.\n\n## Keduanya dapat berada dalam satu workflow\n\nDi beberapa proyek, gambar teknis menjadi acuan detail sementara model 3D membantu diskusi bentuk. Tetapkan dari awal aplikasi mana yang menjadi sumber utama ukuran dan mana yang digunakan untuk visualisasi. Catat unit, orientasi, versi file, dan perubahan penting agar revisi tidak menghapus keputusan tim.\n\nContoh pembagian kerja:\n\n1. Kumpulkan ukuran, batas ruang, dan kebutuhan pemilik proyek.\n2. Buat gambar acuan dengan unit dan layer yang sudah disepakati.\n3. Susun model atau visualisasi sesuai tujuan presentasi.\n4. Cocokkan ukuran penting dengan gambar acuan.\n5. Ekspor hanya format yang diminta dan simpan file sumber.\n\n## Cek perangkat dan versi sebelum memulai\n\nPersyaratan AutoCAD dan SketchUp bergantung pada versi, sistem operasi, ukuran model, serta fitur grafis yang digunakan. Jangan menyimpulkan bahwa semua versi yang tercantum di katalog akan berjalan dengan cara yang sama pada setiap laptop. Baca kebutuhan resmi untuk versi yang tepat dan cocokkan dengan spesifikasi perangkatmu.\n\nKatalog Aplikasi.id mencantumkan [AutoCAD](/produk/app-autocad) dan [SketchUp](/produk/app-sketchup). Sebelum memilih, baca keterangan versi dan kompatibilitas, lalu pastikan jenis lisensi, cara aktivasi, dan dukungan yang ditawarkan dijelaskan dengan terang.\n\n## Rujukan resmi\n\n- [Autodesk: persyaratan sistem AutoCAD](https://www.autodesk.com/support/technical/article/caas/sfdcarticles/sfdcarticles/System-requirements-for-AutoCAD.html)\n- [SketchUp: persyaratan perangkat keras dan perangkat lunak](https://help.sketchup.com/en/sketchup/system-requirements)",
    "category": "Engineering & 3D",
    "author": "Aplikasi.id",
    "author_url": null,
    "cover_image_url": null,
    "published": true
  },
  {
    "slug": "cek-spesifikasi-laptop-sebelum-menjalankan-autocad-sketchup",
    "title": "Cek Spesifikasi Laptop sebelum Menjalankan AutoCAD atau SketchUp",
    "excerpt": "Gunakan daftar cek sistem operasi, prosesor, RAM, grafis, ruang penyimpanan, dan versi aplikasi sebelum memutuskan memasang software desain.",
    "content": "Laptop yang cukup untuk tugas ringan belum tentu nyaman untuk model 3D besar. Sebaliknya, membeli perangkat mahal tanpa mencocokkan kebutuhan software juga belum tentu menyelesaikan masalah. Cek persyaratan berdasarkan aplikasi dan versi yang benar-benar akan digunakan.\n\n## Catat informasi perangkat\n\nSebelum mengunduh, catat nama dan versi sistem operasi, tipe prosesor, kapasitas RAM, model kartu grafis, versi driver, serta ruang penyimpanan kosong. Di Windows, sebagian informasi tersebut dapat dilihat melalui Settings dan alat diagnostik sistem. Di macOS, gunakan menu About This Mac dan System Settings. Jangan hanya menyebut laptop i5 karena generasi prosesor, memori, dan grafisnya dapat berbeda.\n\n## Bedakan minimum dan rekomendasi\n\nHalaman bantuan Autodesk menyediakan persyaratan per versi AutoCAD dan membedakan kebutuhan dasar dari rekomendasi. Halaman SketchUp juga membedakan sistem operasi dan kemampuan grafis; kebutuhan mesin grafis dapat berubah antar versi. Artinya, satu angka RAM atau kartu grafis tidak dapat menjadi patokan universal untuk semua proyek.\n\nUntuk gambar 2D sederhana, ukuran file dan aplikasi lain yang terbuka mungkin berpengaruh besar. Model 3D kompleks, banyak tekstur, atau beberapa aplikasi yang berjalan bersamaan dapat menuntut sumber daya lebih tinggi. Perhatikan juga suhu, daya, dan ruang kerja yang tersedia agar laptop tidak kehabisan ruang saat menyimpan cache atau hasil render.\n\n## Checklist sebelum memasang\n\n- Buka persyaratan resmi untuk versi tepat yang akan dipakai.\n- Pastikan sistem operasi masih didukung oleh versi tersebut.\n- Cocokkan prosesor, RAM, grafis, dan ruang penyimpanan.\n- Perbarui driver grafis dari kanal resmi produsen perangkat atau GPU.\n- Tutup aplikasi yang tidak diperlukan dan simpan salinan proyek.\n- Jika memungkinkan, uji dengan file proyek yang ukurannya mendekati pekerjaan nyata.\n\nKatalog mencantumkan beberapa pilihan [AutoCAD](/produk/app-autocad) dan [SketchUp](/produk/app-sketchup). Versi yang kamu beli atau pasang harus sama dengan yang diperiksa persyaratannya. Tanyakan versi, platform, lisensi, dan metode pemasangan sebelum transaksi. Jangan menonaktifkan fitur keamanan hanya untuk melewati pesan yang tidak kamu pahami.\n\n## Rujukan resmi\n\n- [Autodesk: persyaratan sistem AutoCAD](https://www.autodesk.com/support/technical/article/caas/sfdcarticles/sfdcarticles/System-requirements-for-AutoCAD.html)\n- [Autodesk: komponen hardware yang berpengaruh pada AutoCAD](https://www.autodesk.com/support/technical/article/caas/sfdcarticles/sfdcarticles/Which-hardware-components-are-significant-for-the-use-of-AutoCAD.html)\n- [SketchUp: persyaratan perangkat keras dan perangkat lunak](https://help.sketchup.com/en/sketchup/system-requirements)",
    "category": "Engineering & 3D",
    "author": "Aplikasi.id",
    "author_url": null,
    "cover_image_url": null,
    "published": true
  },
  {
    "slug": "workflow-edit-video-pertama-dengan-davinci-resolve",
    "title": "Workflow Mengedit Video Pertama dengan DaVinci Resolve",
    "excerpt": "Susun folder media, tetapkan pengaturan proyek, buat potongan awal, rapikan suara, lalu ekspor dan periksa hasil sebelum dibagikan.",
    "content": "Proyek video pertama terasa lebih mudah ketika file sumber dan langkah kerja tertata. Sebelum menambahkan efek, siapkan folder proyek dan tentukan tujuan videonya: unggahan vertikal, presentasi, atau video lanskap. Tujuan itu memengaruhi rasio, durasi, dan cara meninjau hasil.\n\n## Rapikan media sejak awal\n\nBuat folder untuk video sumber, audio, gambar, proyek, dan ekspor. Jangan memindahkan atau mengganti nama file sumber setelah proyek mulai ditautkan. Jika media berasal dari beberapa perangkat, salin semuanya ke lokasi kerja yang stabil dan buat cadangan sebelum mengedit.\n\n## Mulai dari cerita, bukan efek\n\nTulis urutan ide dalam beberapa kalimat. Susun klip untuk menyampaikan inti, potong bagian yang tidak perlu, dan pastikan transisi antar gambar mudah diikuti. Periksa dialog dan musik pada headphone atau speaker yang wajar. Musik sebaiknya tidak menutupi suara utama; gunakan audio yang memang boleh kamu pakai.\n\nJika proyek besar terasa lambat, dokumentasi dan pelatihan resmi Blackmagic Design membahas pengelolaan media, proxy, pemotongan, audio, warna, dan ekspor. Pelajari satu bagian yang langsung menyelesaikan hambatanmu sebelum menambah teknik baru. [Panduan resmi DaVinci Resolve](https://www.blackmagicdesign.com/au/products/davinciresolve/training) menyediakan materi latihan untuk pemula maupun pengguna berpengalaman.\n\n## Periksa proyek sebelum ekspor\n\n1. Pastikan resolusi, orientasi, dan frame rate sesuai tujuan.\n2. Putar ulang seluruh timeline dan cari jeda atau potongan yang salah.\n3. Periksa tingkat suara, subtitle, judul, dan ejaan.\n4. Ekspor cuplikan pendek terlebih dahulu untuk memeriksa kualitas.\n5. Putar file ekspor di perangkat yang berbeda sebelum dibagikan.\n\nSimpan file proyek dan media sumber setelah ekspor. Hasil akhir yang sudah jadi tidak selalu cukup untuk memperbaiki revisi berikutnya. Jika penyimpanan terbatas, buat rencana arsip dan pastikan file apa yang harus dipertahankan.\n\nKatalog Aplikasi.id mencantumkan [DaVinci Resolve Studio](/produk/app-davinci). Periksa perbedaan edisi, platform, versi, persyaratan perangkat, dan lisensinya sebelum memilih. Pengaturan yang tersedia dapat berbeda menurut edisi dan versi aplikasi.\n\n## Rujukan resmi\n\n- [Blackmagic Design: pelatihan dan panduan DaVinci Resolve](https://www.blackmagicdesign.com/au/products/davinciresolve/training)\n- [Blackmagic Design: Editor’s Guide untuk DaVinci Resolve](https://documents.blackmagicdesign.com/UserManuals/DaVinci-Resolve-20-Editors-Guide.pdf)",
    "category": "Video & Animasi",
    "author": "Aplikasi.id",
    "author_url": null,
    "cover_image_url": null,
    "published": true
  },
  {
    "slug": "cara-membuat-pdf-hasil-scan-bisa-dicari",
    "title": "Cara Membuat PDF Hasil Scan Bisa Dicari dan Disalin",
    "excerpt": "PDF hasil pemindaian biasanya berupa gambar. OCR dapat menambahkan lapisan teks, tetapi hasilnya tetap perlu dicek sebelum dipakai atau dibagikan.",
    "content": "Pernah mencoba mencari kata di PDF hasil scan tetapi tidak menemukan apa pun? Berkas seperti itu sering menyimpan halaman sebagai gambar, bukan teks yang dapat dipilih. OCR, atau pengenalan karakter optik, membaca gambar dan membuat lapisan teks yang bisa dicari.\n\n## Siapkan scan yang mudah dibaca\n\nPastikan halaman tidak miring, teks cukup jelas, dan seluruh sisi yang dibutuhkan masuk ke bingkai. Simpan salinan scan asli sebelum menjalankan pengenalan teks. Jika ada nomor identitas, tanda tangan, atau informasi pribadi, pastikan kamu memiliki izin untuk memproses dan membagikannya.\n\n## Jalankan OCR dan pilih bahasa yang sesuai\n\nDi Adobe Acrobat, alur umumnya berada pada Scan & OCR lalu Recognize Text. Pilih rentang halaman dan bahasa dokumen. Jika dokumen berisi lebih dari satu bahasa atau banyak istilah khusus, periksa hasilnya dengan lebih teliti. OCR dapat keliru membaca angka, nama orang, tanda baca, tabel, dan huruf yang buram.\n\nAdobe menjelaskan bahwa OCR menambahkan teks yang dapat dipilih dan dicari ke PDF hasil scan. Setelah proses selesai, gunakan pencarian untuk menguji beberapa kata di awal, tengah, dan akhir dokumen. Salin satu paragraf ke dokumen sementara untuk melihat apakah urutan barisnya masuk akal.\n\n## Periksa hasil sebelum dipakai\n\n- Bandingkan nama, tanggal, nomor, dan angka dengan gambar sumber.\n- Periksa tabel dan kolom karena susunannya dapat berubah saat diekstrak.\n- Betulkan kata yang ditandai tidak pasti oleh aplikasi.\n- Pertahankan file scan asli sebagai arsip.\n- Gunakan nama berkas yang menjelaskan isi dan tanggal dokumen.\n\nJangan menganggap hasil OCR sebagai salinan yang sudah diverifikasi. Untuk kontrak, dokumen akademik, atau formulir penting, baca ulang semua bagian yang menentukan keputusan. Jika dokumen akan dipakai pembaca layar, periksa urutan baca dan struktur aksesibilitas secara terpisah.\n\nKatalog mencantumkan [Adobe Acrobat](/produk/app-1788704020346) dan [Nitro PDF Pro](/produk/app-1788703953321). Fitur dan batas tiap versi dapat berbeda. Periksa spesifikasi resmi versi yang ditawarkan sebelum memilih perangkat lunak untuk OCR, konversi, atau penyuntingan PDF.\n\n## Rujukan resmi\n\n- [Adobe: mengenali teks pada PDF hasil scan](https://helpx.adobe.com/in/acrobat/desktop/create-documents/scan-documents-to-pdfs/recognize-text.html)\n- [Adobe: memperbaiki kesalahan pengenalan teks](https://helpx.adobe.com/acrobat/desktop/create-documents/scan-documents-to-pdfs/fix-scanned-text.html)",
    "category": "Office & PDF",
    "author": "Aplikasi.id",
    "author_url": null,
    "cover_image_url": null,
    "published": true
  },
  {
    "slug": "cara-menata-referensi-skripsi-dengan-mendeley",
    "title": "Cara Menata Referensi Skripsi agar Sitasi Tidak Berantakan",
    "excerpt": "Buat pustaka referensi sejak awal, lengkapi metadata, kelompokkan bacaan, dan tetap periksa sitasi otomatis terhadap pedoman kampus.",
    "content": "Daftar pustaka sering baru dirapikan menjelang tenggat, padahal metadata artikel dikumpulkan sedikit demi sedikit selama penelitian. Membuat pustaka referensi sejak awal mengurangi pekerjaan mengetik ulang dan membantu memastikan sumber yang dikutip dapat ditemukan kembali.\n\n## Buat pustaka yang rapi\n\nTambahkan setiap buku, artikel, halaman web, atau laporan saat kamu mulai menggunakannya. Periksa nama penulis, tahun, judul, nama jurnal atau penerbit, halaman, dan DOI atau URL. Data yang diimpor otomatis dapat salah, terutama pada kapitalisasi, urutan nama, atau jenis dokumen.\n\nKelompokkan bacaan menurut pertanyaan riset atau bab, lalu tambahkan catatan singkat tentang temuan dan keterbatasannya. Jangan hanya menyimpan PDF dengan nama acak. Gunakan sistem nama folder atau tag yang masih mudah dipahami setelah beberapa bulan.\n\n## Gunakan sitasi otomatis dengan pemeriksaan manual\n\nReference manager dapat membantu menyimpan dan mencari sumber serta menyisipkan sitasi ke dokumen. Mendeley menyediakan Mendeley Reference Manager dan Mendeley Cite untuk alur tersebut. Namun, perangkat lunak tidak mengetahui pedoman khusus dari kampusmu. Pilih gaya sitasi yang diminta, lalu cocokkan contoh daftar pustaka dengan panduan resmi program studi.\n\nSetelah mengubah gaya, memindahkan bagian, atau menghapus kutipan, perbarui bibliografi dan periksa bahwa semua kutipan dalam teks memiliki entri yang sesuai. Pastikan juga tidak ada sumber pada daftar pustaka yang tidak pernah dirujuk.\n\n## Periksa versi dan dukungan\n\nKatalog Aplikasi.id saat ini mencantumkan [Mendeley Desktop](/produk/app-mendeley). Nama ini berbeda dari Mendeley Reference Manager yang ditawarkan Mendeley saat ini. Cek versi, sistem operasi, plugin Word, sinkronisasi, serta status dukungan produk yang ditawarkan sebelum memasangnya. Dokumentasi resmi Mendeley dapat membantu membedakan produk dan alur yang tersedia.\n\n## Rutinitas sebelum menyerahkan skripsi\n\n1. Periksa ejaan nama dan tahun pada setiap referensi.\n2. Buka DOI atau URL untuk memastikan sumbernya benar.\n3. Cocokkan kutipan langsung dengan halaman sumber dan tandai kutipan sebagai kutipan.\n4. Pastikan gaya sitasi sesuai pedoman kampus.\n5. Simpan salinan dokumen dan ekspor daftar pustaka setelah pemeriksaan.\n\nOtomatisasi menghemat waktu, tetapi tanggung jawab atas akurasi sumber tetap ada pada penulis. Buka sumber asli saat mengutip temuan, dan jangan mencantumkan bacaan yang belum pernah kamu periksa.\n\n## Rujukan resmi\n\n- [Elsevier: Mendeley Reference Manager](https://www.elsevier.com/en-gb/products/mendeley)\n- [Mendeley: panduan Reference Manager, Cite, dan Desktop](https://www.mendeley.com/guides)\n- [Mendeley Support: sistem operasi yang didukung](https://service.elsevier.com/app/answers/detail/a_id/18117/supporthub/mendeley/kw/Operating%2Bsystem/p/16075/track/BvNi_wqrDv8Y~e47Gjga~yKgOCcqPi75Mv9O~zj~PP_H/)",
    "category": "Riset & Produktivitas",
    "author": "Aplikasi.id",
    "author_url": null,
    "cover_image_url": null,
    "published": true
  },
  {
    "slug": "checklist-aman-sebelum-mengunduh-dan-memasang-software",
    "title": "Checklist Aman sebelum Mengunduh dan Memasang Software",
    "excerpt": "Periksa sumber unduhan, kompatibilitas, lisensi, ruang penyimpanan, dan pengaturan keamanan sebelum memasang aplikasi di laptop.",
    "content": "Pemasangan software sebaiknya dimulai dengan pemeriksaan, bukan dengan mematikan peringatan keamanan. File yang tidak cocok atau berasal dari sumber yang tidak jelas dapat merusak pekerjaan dan membahayakan data.\n\n## Periksa sumber dan detail produk\n\nCari halaman resmi penerbit untuk mengetahui nama aplikasi, versi, sistem operasi yang didukung, dan cara pemasangan. Microsoft menyarankan pengguna Windows mengunduh perangkat lunak dari situs resmi atau Microsoft Store serta berhati-hati terhadap sumber pihak ketiga. Hindari file yang meminta kamu menonaktifkan antivirus atau mengubah pengaturan keamanan tanpa penjelasan yang bisa diverifikasi.\n\nSebelum membeli, minta penjelasan tertulis tentang jenis lisensi, siapa pemegang lisensi, berapa perangkat yang boleh memakai, lama aktivasi, pembaruan, batas pemakaian komersial, dan dukungan setelah pembelian. Istilah seperti full version atau lifetime saja belum menjawab semua pertanyaan tersebut.\n\n## Cocokkan perangkat dan siapkan cadangan\n\nPastikan versi aplikasi cocok dengan sistem operasi dan perangkat. Periksa ruang kosong, lokasi pemasangan, koneksi internet yang diperlukan, dan apakah kamu mempunyai hak administrator. Simpan pekerjaan penting dan buat salinan cadangan sebelum perubahan besar. Untuk aplikasi yang akan dipakai di proyek tim, sepakati versi dan format berkas lebih dulu.\n\n## Saat memasang dan setelahnya\n\n- Unduh dari sumber yang jelas dan simpan nama file serta versinya.\n- Baca setiap pilihan pemasangan sebelum melanjutkan.\n- Jangan memberikan kata sandi akun, kode OTP, atau akses jarak jauh kepada pihak yang tidak dikenal.\n- Pertahankan perlindungan keamanan perangkat.\n- Setelah aplikasi terbuka, periksa status lisensi melalui prosedur resmi penerbit.\n- Hapus installer hanya setelah aplikasi berjalan dan salinan cadangan tersedia.\n\nJika sebuah file mengaku sebagai pembaruan, periksa rilis dan instruksi pada kanal penerbit. Jangan memasang crack, keygen, atau patch dari sumber yang tidak resmi. Cara tersebut dapat melanggar lisensi, membuka risiko keamanan, dan membuat aplikasi sulit diperbarui.\n\nKatalog Aplikasi.id menyajikan berbagai [software untuk desain, Office, engineering, video, dan utilitas](/#produk). Baca detail produk, versi, kompatibilitas, dan syarat sebelum transaksi. Jika ada informasi yang belum jelas, tanyakan dulu sebelum mengunduh atau memasang.\n\n## Rujukan resmi\n\n- [Microsoft: panduan menghindari software yang tidak diinginkan](https://learn.microsoft.com/en-us/defender-endpoint/malware/unwanted-software)\n- [Microsoft Learn: risiko pemasangan aplikasi di luar sumber resmi](https://learn.microsoft.com/en-us/windows/application-management/sideload-apps)",
    "category": "Tips Software",
    "author": "Aplikasi.id",
    "author_url": null,
    "cover_image_url": null,
    "published": true
  }
]
